package mz.bam.seeky.android;
import android.app.*;import android.content.pm.PackageInfo;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w320dp-h640dp-mdpi") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Presentation513Test {
    Activity a;@Before public void setup(){a=Robolectric.buildActivity(Activity.class).setup().get();a.setTheme(android.R.style.Theme_Material_NoActionBar);}@After public void close(){UiDialog.dismissAll(a);UiPanel.dismissAll(a);a.finish();}
    void layout(View v){v.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(620,View.MeasureSpec.EXACTLY));v.layout(0,0,320,620);}
    TextView box(String title){TextView b=PlusUi.text(a,title,14);UiBox.style(b);b.setOnClickListener(v->{});return b;}
    @Test public void primaryReadingButtonsAndFollowingCardsHaveVisibleGaps()throws Exception{UiPanel panel=new UiPanel(a,"Livro",null,"book");panel.primary("Ler","Ouvir",()->{},()->{});panel.action("star","Marcar como favorito",null,false,()->{});panel.action("trash","Eliminar",null,false,()->{});panel.show();UiSpacing.apply(panel.root);layout(panel.root);LinearLayout buttons=(LinearLayout)panel.content.getChildAt(0);assertTrue(buttons.getChildAt(1).getLeft()-buttons.getChildAt(0).getRight()>=10);assertTrue(panel.content.getChildAt(1).getTop()-buttons.getBottom()>=10);assertTrue(panel.content.getChildAt(2).getTop()-panel.content.getChildAt(1).getBottom()>=10);Bitmap bitmap=Bitmap.createBitmap(320,620,Bitmap.Config.ARGB_8888);panel.root.draw(new Canvas(bitmap));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+"-513-book-spacing.png")){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    @Test public void adjacentNativeTableCellsAndRowsAreSeparated(){LinearLayout root=new LinearLayout(a);root.setOrientation(1);TableLayout table=new TableLayout(a);TableRow first=new TableRow(a),second=new TableRow(a);for(TableRow row:new TableRow[]{first,second}){row.setBackgroundColor(Color.WHITE);row.addView(box("Coluna A"),new TableRow.LayoutParams(0,52,1));row.addView(box("Coluna B"),new TableRow.LayoutParams(0,52,1));table.addView(row,new TableLayout.LayoutParams(-1,-2));}root.addView(table);a.setContentView(root);UiSpacing.apply(root);layout(root);assertTrue(first.getChildAt(1).getLeft()-first.getChildAt(0).getRight()>=10);assertTrue(second.getTop()-first.getBottom()>=10);}
    @Test public void documentSurfaceCanOptOutWithoutChangingItsFormatting(){LinearLayout body=new LinearLayout(a);body.setOrientation(1);body.addView(box("Documento"),new LinearLayout.LayoutParams(-1,52));body.addView(box("Original"),new LinearLayout.LayoutParams(-1,52));UiSpacing.ignore(body);UiSpacing.apply(body);assertEquals(0,((LinearLayout.LayoutParams)body.getChildAt(1).getLayoutParams()).topMargin);}
    @Test public void applyingSpacingAgainDoesNotAccumulateMargins(){LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.addView(box("Primeiro"));root.addView(box("Segundo"));for(int i=0;i<20;i++)UiSpacing.apply(root);assertEquals(10,((LinearLayout.LayoutParams)root.getChildAt(1).getLayoutParams()).topMargin);}
    @Test public void nonClickableTableCellsAlsoHaveSpace(){TableLayout table=new TableLayout(a);for(int n=0;n<2;n++){TableRow row=new TableRow(a);row.addView(PlusUi.text(a,"Título",14),new TableRow.LayoutParams(0,52,1));row.addView(PlusUi.text(a,"Valor",14),new TableRow.LayoutParams(0,52,1));table.addView(row);}UiSpacing.apply(table);layout(table);TableRow first=(TableRow)table.getChildAt(0);assertTrue(first.getChildAt(1).getLeft()-first.getChildAt(0).getRight()>=10);assertTrue(table.getChildAt(1).getTop()-first.getBottom()>=10);}
    @Test public void diagnosticsUsesTheInstalledPackageVersionAndCode(){PackageInfo info=new PackageInfo();info.packageName=a.getPackageName();info.versionName="5.13.0";info.setLongVersionCode(5002800);shadowOf(a.getPackageManager()).installPackage(info);String report=AppDiagnostics.report(a);assertTrue(report.contains("Seeky 5.13.0 (5002800)"));assertFalse(report.contains("Seeky 5.10.0"));assertFalse(report.contains("api_key"));}
}
